// Accept only bounded PNG/JPEG uploads; filenames are generated by the server.
export function decodeProductImage(data) {
  if (typeof data !== "string" || data.length > 7 * 1024 * 1024)
    throw new Error("รองรับรูปภาพ PNG/JPG ขนาดไม่เกิน 5MB");
  const match = /^data:image\/(png|jpeg);base64,([A-Za-z0-9+/]+={0,2})$/.exec(
    data,
  );
  if (!match) throw new Error("รูปภาพต้องเป็น PNG หรือ JPG");
  const bytes = Buffer.from(match[2], "base64");
  if (bytes.length === 0 || bytes.length > 5 * 1024 * 1024)
    throw new Error("รูปภาพต้องมีขนาดไม่เกิน 5MB");
  const png =
    bytes.length > 24 &&
    bytes
      .subarray(0, 8)
      .equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) &&
    bytes.toString("ascii", 12, 16) === "IHDR";
  const jpeg =
    bytes.length > 4 &&
    bytes[0] === 255 &&
    bytes[1] === 216 &&
    bytes[2] === 255 &&
    bytes.at(-2) === 255 &&
    bytes.at(-1) === 217;
  if (match[1] === "png" ? !png : !jpeg)
    throw new Error("ไฟล์รูปภาพไม่ถูกต้อง");
  if (png) {
    const width = bytes.readUInt32BE(16),
      height = bytes.readUInt32BE(20);
    if (!width || !height || width * height > 40000000)
      throw new Error("ขนาดรูปภาพใหญ่เกินไป");
  }
  return { bytes, extension: match[1] === "png" ? "png" : "jpg" };
}
